function closeStory(){document.querySelector('#storycard').classList.remove('show');storyBusy=false;if(storyQueue.length){const next=storyQueue.shift();setTimeout(()=>showStory(next[0],next[1]),180)}}
document.querySelector('#storyNext').onclick=closeStory;
function addXP(n){xp+=n;while(xp>=100){xp-=100;level++;toast('LEVEL UP · '+level,'A new skill point is yours.')}document.querySelector('#level').textContent='✦ LV '+level;document.querySelector('#xpText').textContent=xp+' / 100 XP'}
function objectiveCount(){return objectives.filter(o=>o.done&&o.type==='beacon').length}
function updateQuest(){const title=document.querySelector('#questTitle'),text=document.querySelector('#questText'),step=document.querySelector('#questStep'),bar=document.querySelector('#progressBar');document.querySelector('#shardCount').textContent='✧ '+shards+' / 6';if(!questStarted){title.textContent='The valley remembers';text.textContent='Find the trailkeeper at the old watchtower.';step.textContent='A new beginning';bar.style.width='8%';return}if(beacons<3){title.textContent='Awaken the waystones';text.textContent='Restore the three old beacons scattered through the vale.';step.textContent=beacons+' / 3 waystones';bar.style.width=(12+beacons*15)+'%'}else if(shards<6){title.textContent='Gather the starlit fragments';text.textContent='The trailkeeper needs six fragments to open the ancient gate.';step.textContent=shards+' / 6 fragments';bar.style.width=(57+shards*5)+'%'}else{title.textContent='Beyond the veil';text.textContent='Return to the northern portal and discover what waits beyond.';step.textContent='The gate is awake';bar.style.width='94%'}}
function interact(){if(storyBusy||gamePaused)return;if(!questStarted){questStarted=true;updateQuest();showStory('ELDER ROWAN','The vale is losing its light. Three waystones have gone quiet, and the old gate is hungry for starlight. Find the beacons, gather the fragments, and come back to me. The path will remember you.');return}if(!interactTarget)return;const o=interactTarget;if(o.type==='npc'){if(beacons<3){showStory('ELDER ROWAN',beacons===0?'The first beacon lies west, beyond the bent pines. Follow the little river, and trust the lights.':'You have awakened '+beacons+' of the three waystones. Listen for their song; it carries farther than you think.')}else if(shards<6){showStory('ELDER ROWAN','The waystones sing again. Now find all six starlit fragments; they are scattered where the old trail meets the wild. Then the north gate can open.')}else{showStory('ELDER ROWAN','You did it. The gate is awake! Beyond it lies the heart of the valley—and the answer to why its light was taken. Go, wayfinder. The story is yours now.');}return}if(o.type==='fragment'){o.done=true;shards++;addXP(25);o.mesh.visible=false;toast('ST★RLIGHT FOUND','A memory returns to the valley.');if(shards===6){storyQueue.push(['THE VALE','Six sparks become a path. To the north, the old gate stirs.']);}updateQuest();return}if(o.type==='beacon'){o.done=true;beacons++;addXP(35);o.mesh.visible=false;toast('WAYSTONE RESTORED','The valley brightens around you.');if(beacons===3)storyQueue.push(['THE VALE','Three lights answer one another across the hills. The northern gate is calling.']);updateQuest();return}if(o.type==='portal'){if(beacons<3||shards<6){toast('THE GATE IS QUIET','Restore all waystones and find six fragments.');return}gamePaused=true;openPanel('THE STORY CONTINUES','You cross the threshold. Somewhere beyond the veil, a lost sun is waiting.','The first chapter is complete. Your journey through the Shattered Vale has only just begun.','✦ CHAPTER COMPLETE','Continue exploring');}}
function openPanel(eyebrow,title,body,action='Resume journey',secondary=''){document.querySelector('#panelEyebrow').textContent=eyebrow;document.querySelector('#panelTitle').textContent=title;document.querySelector('#panelBody').textContent=body;document.querySelector('#panelContent').innerHTML='';const actions=document.querySelector('#panelActions');actions.innerHTML='';const b=document.createElement('button');b.className='panelbutton';b.textContent=action;b.onclick=()=>{document.querySelector('#panelback').classList.remove('open');gamePaused=false};actions.appendChild(b);if(secondary){const c=document.createElement('button');c.className='panelbutton secondary';c.textContent=secondary;c.onclick=()=>showMap();actions.appendChild(c)}document.querySelector('#panelback').classList.add('open')}
function showMenu(){gamePaused=true;openPanel('PAUSED','Take a breath, wayfinder','The valley is still here when you are ready.','Resume journey','Field guide');document.querySelector('#panelActions').lastChild.onclick=()=>showMap()}
function showMap(){gamePaused=true;document.querySelector('#panelback').classList.add('open');document.querySelector('#panelEyebrow').textContent='FIELD GUIDE';document.querySelector('#panelTitle').textContent='Your journey';document.querySelector('#panelBody').textContent='A quiet world of ancient forests, hidden lights, and a story waiting to be found.';document.querySelector('#panelContent').innerHTML=`<div class="statgrid"><div class="stat"><b>${shards}/6</b><span>FRAGMENTS</span></div><div class="stat"><b>${beacons}/3</b><span>WAYSTONES</span></div><div class="stat"><b>${level}</b><span>WAYFINDER</span></div></div><p><b style="color:#ffdc9b">Controls</b><br>Move with the left stick or WASD. Drag anywhere to look around. Jump over rocks and use the ✧ skill to dash. Approach a person or glowing object and tap the action prompt.</p>`;const a=document.querySelector('#panelActions');a.innerHTML='';const b=document.createElement('button');b.className='panelbutton';b.textContent='Back to the vale';b.onclick=()=>{document.querySelector('#panelback').classList.remove('open');gamePaused=false};a.appendChild(b)}
document.querySelector('#mapBtn').onclick=showMap;document.querySelector('#menuBtn').onclick=showMenu;document.querySelector('#closePanel').onclick=()=>{document.querySelector('#panelback').classList.remove('open');gamePaused=false};document.querySelector('#interact').onclick=interact;

