const mapCanvas=document.querySelector('#mapCanvas'),mapCtx=mapCanvas.getContext('2d');function drawMap(){const c=mapCtx;c.clearRect(0,0,180,180);c.fillStyle='#28443d';c.fillRect(0,0,180,180);c.strokeStyle='#89b78b';c.lineWidth=7;c.beginPath();for(let i=0;i<80;i++){let t=i/79*11.4,x=90+Math.sin(t*.72)*21*1.03,y=90+Math.cos(t*.72)*21*1.03;i?c.lineTo(x,y):c.moveTo(x,y)}c.stroke();for(const o of objectives){if(o.done)continue;const x=90+o.x*.78,y=90+o.z*.78;c.fillStyle=o.type==='beacon'?'#65f3da':'#ffce78';c.beginPath();c.arc(x,y,3.8,0,Math.PI*2);c.fill()}c.fillStyle='#f6d29a';c.beginPath();c.arc(90+player.position.x*.78,90+player.position.z*.78,4,0,Math.PI*2);c.fill();c.strokeStyle='#fff';c.lineWidth=1.5;c.stroke()}
